def semver_sort(versions):
    def parse_version(v):
        # Split build metadata (+ sign)
        if '+' in v:
            v, build = v.split('+', 1)
        else:
            build = None

        # Split pre-release (- sign)
        if '-' in v:
            core, prerelease = v.split('-', 1)
        else:
            core = v
            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        parts = core.split('.')
        major, minor, patch = int(parts[0]), int(parts[1]), int(parts[2])

        # Parse pre-release identifiers
        prerelease_identifiers = []
        if prerelease:
            for identifier in prerelease.split('.'):
                if identifier.isdigit():
                    prerelease_identifiers.append((0, int(identifier)))
                else:
                    prerelease_identifiers.append((1, identifier))

        return (major, minor, patch, prerelease_identifiers)

    def sort_key(v):
        major, minor, patch, prerelease_identifiers = parse_version(v)

        # No pre-release sorts after pre-release
        if not prerelease_identifiers:
            has_prerelease = (1,)
        else:
            has_prerelease = (0,)

        return (major, minor, patch, has_prerelease, prerelease_identifiers)

    # Stable sort to maintain input order for equal precedence
    return sorted(versions, key=sort_key)

